          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    cypher = "BEGIN"
    if mode:
        cypher += (" {mode}").format(mode=mode)
    if bookmarks:
        cypher += (" USING " + bookmarks)
    if metadata:
        cypher += (" {metadata}").format(metadata=metadata)
    if timeout:
        cypher += (" USING TIMEOUT {timeout}".format(timeout=timeout)
    if db:
        cypher += (" {}".format(db))
