def legacy_merge_orderings(orderings):
    # Initialize an empty list to store the merged orderings
    merged_orderings = []

    # Loop through each ordering in the input list
    for ordering in orderings:
        # Check if the current ordering is empty
        if not ordering:
            continue

        # Loop through the elements in the current ordering
        for element in ordering:
            # Check if the current element is already in the merged orderings list
            if element in merged_orderings:
