        raise TypeError("many_params must be an iterable")

    # Initialize variables
    param_styles = [None] * len(many_params)
    out_params = [None] * len(many_params)

    # Format each set of parameters
    for i, params in enumerate(many_params):
        if not isinstance(params, Mapping) and not isinstance(params, Sequence):
            raise TypeError("params must be a mapping or sequence")

        if isinstance(params, Mapping):
            param_styles[i] = "named"
            out_params[i] = [
                (k, v) for k, v in params.items() if k.isidentifier()
            ]
        else:
            param_styles[i] = "ordinal"
            out_params[i] = list(params)

    # Convert the SQL query to use the out-style parameters
    formatted_sql = sql.replace("?", "@out{}")
    for i, style in enumerate(param_styles):
        if style == "named":
