    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """

    # Check if the given path exists in the pyfs object
    if path not in self.fs or self.fs[path] is None:
        raise ValueError("Path does not exist")

    # Check if the given path points to an OCFL object
    if not self.fs[path].is_ocfl_object():
