def _fromutc(self, dt):
    if dt.tzinfo is None:
        raise ValueError("dt.tzinfo cannot be None")
    tz = dt.tzinfo
    utcoffset = tz.utcoffset(dt)
    if utcoffset is None:
        raise ValueError("dt does not have a UTC offset")
    next_t = dt + timedelta(seconds=1)
    next_offset = tz.utcoffset(next_t)
    if next_offset is None:
        raise ValueError("next_t does not have a UTC offset")
    if next_offset - utcoffset != timedelta(0):
        dt = dt - timedelta(0, 1)
    return dt.astimezone(self)
