def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    import subprocess
    import shlex
    import sys

    if isinstance(commands, str):
        commands = [commands]

    process = None
    for command in commands:
        command_list = shlex.split(command)
        if not command_list:
            continue
        if cwd is not None:
            process = subprocess.Popen(command_list, cwd=cwd, env=env,
                                        stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        else:
            process = subprocess.Popen(command_list, env=env,
                                        stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if hide_stderr:
            err = process.stderr.read()
        else:
            err = ''
        out = process.stdout.read().decode()
        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, command)
        if verbose:
            print(out)
        if env is not None:
            print(env)
        break

    if process is None:
        raise ValueError("invalid command")

    return out, err

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    import subprocess

    if isinstance(commands, str):
        commands = [commands]

    if env is None:
        env = os.environ.copy()

    for command in commands:
        try:
            if verbose:
                print(f"Running command: {command}", file=sys.stderr)

            subprocess.run(command, shell=True, cwd=cwd, env=env, check=True)

            if hide_stderr:
                # hide stderr output
                subprocess.run(command, shell=True, cwd=cwd, env=env, check=True, stderr=subprocess.DEVNULL)
        except subprocess.CalledProcessError:
            print(f"Error running command: {command}", file=sys.stderr)
            sys.exit(1)

