def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        # Find the duplicate key value and the corresponding mapping node
        key_node, value_node = node
        key = key_node.value
        mapping_node = value_node

        # Look for the existing mapping node in the result with the same key
        for i, (result_key_node, result_mapping_node) in enumerate(result):
            if result_key_node.value == key:
                break
        else:
            # If there is no existing node with the same key, add it to the result
            result.append((key_node, mapping_node))
            continue

        # Deep merge the value of the mapping node with the corresponding one in the result
        new_value_node = deep_merge(result_mapping_node.value, mapping_node.value)
        result[i] = (key_node, new_value_node)

    return result

