def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse
    global_namespace = argparse.Namespace()
    subparser_names = []
    for unparsed_argument in unparsed_arguments:
        parser = argparse.ArgumentParser()
        subparser_name, args = parser.parse_known_args(unparsed_argument)
        if subparser_name not in subparser_names:
            subparser_names.append(subparser_name)
        subparser_namespace = parser.parse_args(args)
        if subparser_name == "global":
            global_namespace = subparser_namespace
        else:
            setattr(global_namespace, subparser_name, subparser_namespace)

    return {subparser_name: subparser_namespace for subparser_name in subparser_names}

