def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        key, value = node
        # Find the index of the key in the result. If the key is not in the result, add a new entry.
        try:
            index = next(i for i, (k, _) in enumerate(result) if k == key)
        except StopIteration:
            result.append((key, value))
            continue

        # If the value is a ScalarNode, simply overwrite the existing value.
        if isinstance(value, ruamel.yaml.nodes.ScalarNode):
            result[index] = (key, value)
            continue

        # If the value is a MappingNode, merge it with the existing MappingNode.
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            result_value = result[index][1]
            if not isinstance(result_value, ruamel.yaml.nodes.MappingNode):
                continue

            # Merge the existing MappingNode with the new MappingNode.
            for subnode in value.value:
                subkey, subvalue = subnode
                # If the subkey is already in the result, merge the subvalues.
                if subkey in result_value.value:
                    index_ = next(i for i, (k, _) in enumerate(result_value.value) if k == subkey)
                    subvalue = merge_nodes(result_value.value[index_][1], subvalue)
                result_value.value.append((subkey, subvalue))

    return result

